SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, a.dischtime - a.admittime AS los, percent_rank() OVER (PARTITION BY p.gender, p.anchor_year_group ORDER BY (a.dischtime - a.admittime) NULLS LAST) AS percentile_rank, CASE WHEN p.dod IS NOT NULL THEN 'death' WHEN a.discharge_location IS NOT NULL THEN 'home' WHEN a.discharge_location = 'ICU' THEN 'ICU' ELSE 'other' END AS discharge_category FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND p.anchor_age = 49 AND p.anchor_year BETWEEN 44 AND 54 AND a.discharge_location IS NOT NULL AND a.dischtime - a.admittime BETWEEN 7 AND 14;